template:
#[derive(Debug, PartialEq, Default)]
struct Config {
    port: u16,
    host: String,
}

fn main() {
    let cfg = Config {
        port: 8080,
        ⟦slot1⟧
    };
    let empty = Config⟦slot2⟧;
    assert_eq!(cfg.host, "");
    assert_eq!(empty.port, 0);
}

tests:
#[test]
fn test_defaults() {
    let cfg = Config { port: 80, ..Default::default() };
    assert_eq!(cfg.port, 80);
    assert_eq!(cfg.host, "");
}
